// The headline numbers and findings, as a card. Python wrote the sentences;
// this cell lays them out. It sets its own colours, so it reads the same in any theme.
const h = nb.get('headline');
const findings = nb.get('findings') ?? [];
if (!h) return '<p>Run the Python cells above first.</p>';

const money = (n) => '£' + n.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (text) => String(text).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const tile = (label, value, colour) => `<div class="tile"><div class="label">${label}</div><div class="value" style="color:${colour}">${value}</div></div>`;

return `
<style>
  .card { background: #0f172a; color: #e2e8f0; font: 14px/1.5 system-ui, sans-serif; border-radius: 12px; padding: 16px 20px; }
  h3 { margin: 0 0 12px; color: #f8fafc; font-size: 16px; }
  .tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
  .tile { background: #1e293b; border-radius: 10px; padding: 10px 12px; }
  .label { color: #94a3b8; font-size: 12px; }
  .value { font-size: 22px; font-weight: 700; }
  ul { margin: 14px 0 0; padding-left: 20px; }
  li { margin: 4px 0; }
</style>
<div class="card">
  <h3>At a glance</h3>
  <div class="tiles">
    ${tile('Money raised', money(h.raised), '#38bdf8')}
    ${tile('Profit for the school', money(h.profit), '#4ade80')}
    ${tile('Sales', h.sales.toLocaleString(), '#facc15')}
    ${tile('Stalls', h.stalls, '#f472b6')}
  </div>
  <ul>${findings.map((line) => `<li>${esc(line)}</li>`).join('')}</ul>
</div>`;

// Where the money went, stall by stall. Hover a bar for the numbers.
const summary = nb.get('summary') ?? [];
const parts = summary.flatMap((s) => [
  { stall: s.stall, part: 'Profit', amount: s.profit, sold: s.sold },
  { stall: s.stall, part: 'Costs', amount: s.costs, sold: s.sold },
]);

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Each stall\'s takings, split into costs and profit',
  width: 560,
  height: 200,
  data: { values: parts },
  mark: { type: 'bar', cornerRadiusEnd: 2 },
  encoding: {
    y: { field: 'stall', type: 'nominal', sort: summary.map((s) => s.stall), title: null },
    x: { field: 'amount', type: 'quantitative', stack: true, title: 'Money taken (£)' },
    color: { field: 'part', type: 'nominal', title: null, scale: { domain: ['Profit', 'Costs'], range: ['#22c55e', '#94a3b8'] } },
    order: { field: 'part', sort: 'descending' },
    tooltip: [
      { field: 'stall', title: 'Stall' },
      { field: 'part', title: 'Part' },
      { field: 'amount', title: '£', format: ',.2f' },
      { field: 'sold', title: 'Sales' },
    ],
  },
};
